 {"genre":"seiji","diff":1,"era":"yayoi","q":"弥生時代の倭（日本）について書かれた、有名な中国の歴史書はどれですか。","c":["魏志倭人伝","古事記","日本書紀","枕草子"],"a":0,"desc":"『魏志倭人伝』は中国の歴史書で、当時の倭（日本）の様子や卑弥呼・邪馬台国について記しています。"},
 {"genre":"seiji","diff":2,"era":"yayoi","q":"景初3年（239年）ごろ、卑弥呼が使いを送った中国の国はどこですか。","c":["魏（ぎ）","唐（とう）","隋（ずい）","秦（しん）"],"a":0,"desc":"卑弥呼は景初3年＝239年ごろ、中国の魏に使いを送りました（朝貢）。当時の中国は魏・呉・蜀に分かれた三国時代でした。（原文を景初二年＝238年と読む説もありますが、教科書では239年ごろとするのがふつうです。）"},
 {"genre":"seiji","diff":2,"era":"yayoi","q":"239年ごろの朝貢で、魏の皇帝が卑弥呼にあたえたとされる称号は何ですか。","c":["親魏倭王","漢委奴国王","日出づる処の天子","征夷大将軍"],"a":0,"desc":"魏の皇帝は卑弥呼に「親魏倭王」の称号と、その金印（親魏倭王の金印・紫綬つき）、銅鏡百枚などをあたえたと『魏志倭人伝』に記されています。"},
 {"genre":"seiji","diff":2,"era":"yayoi","q":"卑弥呼が魏へ送り、『魏志倭人伝』にも名が残る使者は誰ですか。","c":["難升米（なしめ）","小野妹子","阿倍仲麻呂","行基"],"a":0,"desc":"難升米は卑弥呼が魏へ送った使者で、『魏志倭人伝』にその名が記されています。"},
 {"genre":"seiji","diff":3,"era":"yayoi","q":"弥生時代に倭からあたえられた「2つの金印」について、正しい組み合わせはどれですか。","c":["57年に奴国の王が漢から授かった『漢委奴国王』と、239年ごろに卑弥呼が魏から授かった『親魏倭王』","どちらも卑弥呼が魏から同時に授かった","どちらも奴国の王が漢から授かった","どちらも江戸時代につくられた"],"a":0,"desc":"金印は2つあります。57年に奴国の王が後漢から授かった「漢委奴国王」（志賀島出土）と、239年ごろに卑弥呼が魏から授かった「親魏倭王」の金印です。時代も国もちがう別の金印なので、混同しないようにしましょう。"},
 {"genre":"seiji","diff":3,"era":"yayoi","q":"邪馬台国と対立し、卑弥呼と争った南の国はどれですか。","c":["狗奴国（くなこく）","奴国","投馬国","伊都国"],"a":0,"desc":"狗奴国は男王・卑弥弓呼が治め、邪馬台国の卑弥呼と争ったと『魏志倭人伝』に記されています。"},
 {"genre":"seiji","diff":2,"era":"yayoi","q":"57年、奴国（なこく）の王が使いを送って金印「漢委奴国王」を授かったとされる、当時の中国の国はどれですか。","c":["漢（後漢）","魏","唐","明"],"a":0,"desc":"『後漢書』には、57年に奴国の王が後漢に使いを送り、金印を授かったと記されています。これが志賀島で見つかった「漢委奴国王」の金印にあたると考えられています。"},
 {"genre":"seiji","diff":2,"era":"yayoi","q":"福岡県の志賀島（しかのしま）で見つかり、奴国の王が漢から授かったとされる金印に刻まれた文字はどれですか。","c":["漢委奴国王","親魏倭王","天皇御璽","大宝律令"],"a":0,"desc":"志賀島で見つかった金印には「漢委奴国王」と刻まれており、57年に奴国の王が後漢の皇帝から授かったものと考えられています。卑弥呼が魏から授かる「親魏倭王」の金印とは別の金印です。"},
 {"genre":"ninbo","diff":1,"era":"yayoi","q":"まじない（鬼道）で神の意を聞き、倭の女王として人々を従えたとされる人物は誰ですか。","c":["卑弥呼","推古天皇","持統天皇","北条政子"],"a":0,"desc":"卑弥呼はまじない（鬼道）によって人々を従えた邪馬台国の女王で、めったに人前に姿を見せなかったと伝えられます。"},
 {"genre":"ninbo","diff":2,"era":"yayoi","q":"『魏志倭人伝』によると、卑弥呼は何によって人々を従えたとされていますか。","c":["まじない（鬼道）","強い軍隊","たくさんの財宝","美しい歌"],"a":0,"desc":"卑弥呼は鬼道とよばれるまじないで神の意を伝え、人々の心をひとつにして従えたとされています。"},
 {"genre":"ninbo","diff":2,"era":"yayoi","q":"『魏志倭人伝』によると、人前にめったに姿を見せない卑弥呼の政（まつりごと）を助けたのは誰ですか。","c":["卑弥呼の弟","卑弥呼の夫","中国の皇帝","狗奴国の王"],"a":0,"desc":"卑弥呼はめったに人前に出ず、神事に専念し、ただ一人の弟が政（まつりごと）を助けたと『魏志倭人伝』に記されています。神に仕える者がくにを束ねる、倭独自のかたちです。"},
 {"genre":"ninbo","diff":2,"era":"yayoi","q":"卑弥呼が神の意を聞くために用いたとされる、まじないのことを『魏志倭人伝』では何とよんでいますか。","c":["鬼道（きどう）","律令","御成敗式目","参勤交代"],"a":0,"desc":"卑弥呼のまじないは「鬼道」とよばれます。卑弥呼はこの宗教的な力で人々の心をつかみ、くにを束ねたとされています。"},
 {"genre":"ninbo","diff":3,"era":"yayoi","q":"卑弥呼の死後、再び乱れた倭をまとめるために女王となり、人々の心をふたたびひとつにした卑弥呼の一族の少女は誰ですか。","c":["壹与（いよ）","推古","額田王","和気広虫"],"a":0,"desc":"卑弥呼の死後、男王が立つと国が乱れたため、一族の少女・壹与（いよ）がわずか十三歳で女王となり、宗教的な権威で人心をまとめ、国はふたたび治まったとされます。"}
